import json
import logging
import threading
import boto3
import cfnresponse



def copy_objects(source_bucket, dest_bucket, prefix, objects):
    s3 = boto3.client('s3')
    for o in objects:
        key = prefix + o
        copy_source = {
            'Bucket': source_bucket,
            'Key': key
        }
        print('copy_source: %s' % copy_source)
        print('dest_bucket = %s'%dest_bucket)
        print('key = %s' %key)
        s3.copy_object(CopySource=copy_source, Bucket=dest_bucket,
              Key=key)


def timeout(event, context):
    logging.error('Execution is about to time out, sending failure response to CloudFormation')
    cfnresponse.send(event, context, cfnresponse.FAILED, {}, None)

def romanscorch(bucket):

    s3_client = boto3.client('s3')
    object_response_paginator = s3_client.get_paginator('list_object_versions')

    delete_marker_list = []
    version_list = []

    for object_response_itr in object_response_paginator.paginate(Bucket=bucket):
        if 'DeleteMarkers' in object_response_itr:
            for delete_marker in object_response_itr['DeleteMarkers']:
                delete_marker_list.append({'Key': delete_marker['Key'], 'VersionId': delete_marker['VersionId']})

        if 'Versions' in object_response_itr:
            for version in object_response_itr['Versions']:
                version_list.append({'Key': version['Key'], 'VersionId': version['VersionId']})

    for i in range(0, len(delete_marker_list), 1000):
        response = s3_client.delete_objects(
            Bucket=bucket,
            Delete={
                'Objects': delete_marker_list[i:i+1000],
                'Quiet': True
            }
        )
        print(response)

    for i in range(0, len(version_list), 1000):
        response = s3_client.delete_objects(
            Bucket=bucket,
            Delete={
                'Objects': version_list[i:i+1000],
                'Quiet': True
            }
        )
        print(response)


def handler(event, context):
    print(json.dumps(event))
    _ret = {}
    timer = threading.Timer((context.get_remaining_time_in_millis()
              / 1000.00) - 0.5, timeout, args=[event, context])
    timer.start()
    status = cfnresponse.SUCCESS


    try:
        source_bucket = event['ResourceProperties']['SourceBucket']
        dest_bucket = event['ResourceProperties']['DestBucket']
        prefix = event['ResourceProperties']['prefix']
        objects = event['ResourceProperties']['Objects']
        if event['RequestType'] == 'Delete':

            romanscorch(event['ResourceProperties']['DestBucket'])
        else:
            copy_objects(source_bucket, dest_bucket, prefix, objects)
    except Exception as e:
        logging.error('Exception: %s' % e, exc_info=True)
        status = cfnresponse.FAILED
    finally:
        timer.cancel()
        cfnresponse.send(event, context, status, {}, None)
        return _ret
